// Extract user message and session data
const userMessage = $input.item.json.message || '';
const sessionId = $input.item.json.sessionId || $jmespath('[0].json.id', $input.all());
const userName = $input.item.json.userName || 'Guest';

// Get conversation history from previous items or initialize
const conversationHistory = $input.item.json.conversationHistory || [];

// Add user message to history
conversationHistory.push({
  role: 'user',
  content: userMessage,
  timestamp: new Date().toISOString()
});

return {
  json: {
    userMessage,
    sessionId,
    userName,
    conversationHistory,
    messageCount: conversationHistory.length
  }
};

// Extract AI response
const aiResponse = $input.item.json.choices[0].message.content;

// Get conversation data from previous step
const conversationHistory = $('Prepare Conversation Data').item.json.conversationHistory;

// Add AI response to history
conversationHistory.push({
  role: 'assistant',
  content: aiResponse,
  timestamp: new Date().toISOString()
});

// Analyze intent for lead qualification
const userMessage = $('Prepare Conversation Data').item.json.userMessage.toLowerCase();
const sessionId = $('Prepare Conversation Data').item.json.sessionId;
const userName = $('Prepare Conversation Data').item.json.userName;

// Intent detection
const intents = {
  booking: /\b(book|reserve|availability|book now|make a booking)\b/i.test(userMessage),
  pricing: /\b(cost|price|expensive|how much|rate|fee)\b/i.test(userMessage),
  permits: /\b(permit|gorilla permit|booking permit)\b/i.test(userMessage),
  dates: /\b(when|dates|available|visit in|traveling in|january|february|march|april|may|june|july|august|september|october|november|december|2024|2025)\b/i.test(userMessage),
  contact: /\b(email|phone|call|contact|reach you|get in touch)\b/i.test(userMessage)
};

// Calculate lead score based on intent signals
let leadScore = 0;
if (intents.booking) leadScore += 30;
if (intents.pricing) leadScore += 10;
if (intents.permits) leadScore += 20;
if (intents.dates) leadScore += 25;
if (intents.contact) leadScore += 15;

// Boost score based on message count (engagement)
const messageCount = conversationHistory.length / 2; // Divide by 2 for user messages only
if (messageCount >= 3) leadScore += 15;
if (messageCount >= 5) leadScore += 10;

// Determine if this should trigger lead qualification
const shouldQualifyLead = leadScore >= 40 || intents.contact;

return {
  json: {
    response: aiResponse,
    sessionId,
    userName,
    conversationHistory,
    intents,
    leadScore,
    shouldQualifyLead,
    timestamp: new Date().toISOString()
  }
};
